const env = vars.env || undefined;
const plan = await tools.fixture_plan({ env, service: vars.service || undefined, seeds: [{ db: vars.db, table: vars.table, where: vars.where }] });
let capture = await tools.fixture_capture({ plan, mask: true });
for (let i = 0; i < 120 && capture.state === 'running'; i++) { await new Promise(r => setTimeout(r, 1000)); capture = await tools.fixture_capture({ job: capture.job }); }
if (capture.state !== 'done') throw new Error(`capture ${capture.state}: ${capture.error || 'not finished'}`);
const validation = await tools.fixture_validate({ capture: capture.capture });
const exported = await tools.fixture_export({ workspace: vars.workspace, capture: capture.capture, name: vars.name });
test('rows were captured', () => expect(capture.counts?.rows || 0).toBeGreaterThan(0));
return { capture: capture.capture, counts: capture.counts, complete: capture.complete, gaps: Object.entries((capture.gaps || []).reduce((n, g) => (n[g.kind] = (n[g.kind] || 0) + 1, n), {})).map(([kind, count]) => `${kind}: ${count}`), validation: { complete: validation.complete, gaps: (validation.gaps || []).length }, directory: exported.directory || exported.path, files: exported.files, next: capture.complete ? `checks reuse-data with name=${vars.name}, or test_run with fixture_path=${exported.directory || exported.path}` : 'incomplete capture: resolve the gaps (seed the missing reads, or leave service empty) before building a reusable base' };
